class Widget {
public:
  int magicValue() const {
    if (cacheValid) return cachedValue;
    else {
      auto val = 1; // Represents expensive computation

      // RACE CONDITION WINDOW:
      // Thread 1 writes to cachedValue here...
      cachedValue = val;                  // uh oh, part 1
      // ...but a context switch could happen before it writes to cacheValid.
      // Thread 2 could enter, see cacheValid as false, and re-do the work.
      cacheValid = true;                  // uh oh, part 2

      return cachedValue;
    }
  }
private:
  mutable std::atomic<bool> cacheValid{ false };
  mutable std::atomic<int> cachedValue;
};
